    bg = next(v for row in grid for v in row if v != 8)
    out = [row[:] for row in grid]
    seen = set()
    q = deque()
    # Mark all background cells reachable from the boundary.
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == bg and (r, c) not in seen:
                seen.add((r, c))
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == bg and (r, c) not in seen:
                seen.add((r, c))
                q.append((r, c))
    while q:
